import{_ as r,C as d,o as t,c as s,a5 as o,b as c,w as i,a as n,E as l,a7 as g}from"./chunks/framework.QWVCgkrI.js";const u=JSON.parse('{"title":"Gitのステージング — 作業ツリー・index・HEAD","description":"","frontmatter":{"title":"Gitのステージング — 作業ツリー・index・HEAD","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"tools","summary":"git addの後で再編集した例から、作業ツリー・index・HEADが示すファイルの版を見分け、indexのパスとblob IDから次のコミットのtreeが作られる仕組みを追う。","aliases":["Git index","staging area","ステージング領域","作業ツリー","git diff --cached","git ls-files --stage","git write-tree"],"verification":"Git公式データモデルとコマンド資料に照合し、Windowsの独立したGitリポジトリでindex・差分・次のtreeを確認（2026-11-17）"}},"headers":[],"relativePath":"tools/git-staging-index.md","filePath":"tools/git-staging-index.md"}'),h={name:"tools/git-staging-index.md"};function f(p,e,m,E,x,b){const a=d("Mermaid");return t(),s("div",null,[e[1]||(e[1]=o('<h1 id="gitのステージング-—-作業ツリー・index・head" tabindex="-1">Gitのステージング — 作業ツリー・index・HEAD <a class="header-anchor" href="#gitのステージング-—-作業ツリー・index・head" aria-label="Permalink to &quot;Gitのステージング — 作業ツリー・index・HEAD&quot;">​</a></h1><p>ゲームの検証用の <code>score.txt</code> を <code>score=0</code> から <code>score=10</code> に変え、<code>git add</code> したとします。その後で <code>score=20</code> に変えても、通常のコミットに入るのは <code>score=10</code> です。<a href="/study/tools/git-basics.html">Gitの基本</a>に出てくるこの例を、今回はどの版がどこにあり、次のtreeが何を参照するかという観点から見ていきます。</p><h2 id="同じパスに3つの版がある" tabindex="-1">同じパスに3つの版がある <a class="header-anchor" href="#同じパスに3つの版がある" aria-label="Permalink to &quot;同じパスに3つの版がある&quot;">​</a></h2><p>作業ツリーには、エディターで最後に保存した <code>score=20</code> があります。<strong>index</strong>（ステージング領域）には <code>git add</code> した時点でGitが記録する <code>score=10</code> を指す項目が残ります。<strong>HEAD</strong> が示す現在のコミットのtreeには、最後にコミットした <code>score=0</code> があります。<code>git add</code> はindexを更新します。再編集後の内容も入れたいときは、もう一度ステージします。<a href="https://git-scm.com/docs/git-add#_description" target="_blank" rel="noreferrer">git-add</a> · <a href="https://git-scm.com/docs/gitdatamodel#index" target="_blank" rel="noreferrer">Git公式のデータモデル</a></p>',4)),(t(),c(g,null,{default:i(()=>[l(a,{id:"mermaid-12",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20accTitle%3A%20score.txt%E3%81%AE3%E3%81%A4%E3%81%AE%E7%89%88%E3%81%A8%E5%B7%AE%E5%88%86%E3%81%AE%E6%AF%94%E8%BC%83%E6%96%B9%E5%90%91%0A%20%20%20%20accDescr%3A%20HEAD%E3%81%AEscore%3D0%E3%81%8B%E3%82%89index%E3%81%AEscore%3D10%E3%82%92%E6%AF%94%E8%BC%83%E3%81%99%E3%82%8B%E3%81%AE%E3%81%8Cdiff%20--cached%E3%80%82index%E3%81%AEscore%3D10%E3%81%8B%E3%82%89%E4%BD%9C%E6%A5%AD%E3%83%84%E3%83%AA%E3%83%BC%E3%81%AEscore%3D20%E3%82%92%E6%AF%94%E8%BC%83%E3%81%99%E3%82%8B%E3%81%AE%E3%81%8Cdiff%E3%80%82%0A%20%20%20%20h%5B%22HEAD%E3%80%80score%3D0%22%5D%20--%3E%7Cdiff%20--cached%7C%20i%5B%22index%E3%80%80score%3D10%22%5D%0A%20%20%20%20i%20--%3E%7Cdiff%7C%20w%5B%22%E4%BD%9C%E6%A5%AD%E3%83%84%E3%83%AA%E3%83%BC%E3%80%80score%3D20%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o(`<p>図の矢印は、差分の比較元から比較先へ向いています。<code>git diff -- score.txt</code> ではindexの <code>score=10</code> が <code>-</code>、作業ツリーの <code>score=20</code> が <code>+</code> です。<code>git diff --cached -- score.txt</code> ではHEADの <code>score=0</code> が <code>-</code>、indexの <code>score=10</code> が <code>+</code> です。後者は比較するコミットを省略し、HEADにコミットがある場合の説明です。<code>--staged</code> も同じ意味で使えます。<a href="https://git-scm.com/docs/git-diff#_description" target="_blank" rel="noreferrer">git-diff</a></p><p>このとき <code>git status --short</code> は、<code>score.txt</code> に <code>MM</code>、作業ツリーにだけある <code>bonus.txt</code> に <code>??</code> を表示しました。競合のない例で、左の <code>M</code> はHEADとindexの間、右の <code>M</code> はindexと作業ツリーの間に変更があるという意味です。この <code>bonus.txt</code> は未追跡で、indexのコミット候補に登録されていません。通常の <code>git diff</code> と <code>git diff --cached</code> にもこの新規ファイルの内容は出ません。<a href="https://git-scm.com/docs/git-status#_short_format" target="_blank" rel="noreferrer">git-statusの短縮形式</a> · <a href="https://git-scm.com/docs/git-diff#_description" target="_blank" rel="noreferrer">git-diff</a></p><h2 id="indexは次のスナップショットの項目を持つ" tabindex="-1">indexは次のスナップショットの項目を持つ <a class="header-anchor" href="#indexは次のスナップショットの項目を持つ" aria-label="Permalink to &quot;indexは次のスナップショットの項目を持つ&quot;">​</a></h2><p>indexを読むと、変更箇所だけではなく、次のコミットで使うパスと保存内容の対応が見えます。通常のファイルの項目にはパス、モード、blob IDなどがあります。<code>git ls-files --stage</code> の表示はモード、オブジェクトID、ステージ番号、パスの順です。この例の <code>0</code> は競合していない項目です。マージ競合中の1〜3は、基準・現在側・相手側の版を区別する番号です。<a href="/study/tools/git-three-way-merge.html">Gitのマージ</a>に具体例があります。<code>git show &#39;:score.txt&#39;</code> はそのindex項目が指すblobを、<code>git show &#39;HEAD:score.txt&#39;</code> はHEADのコミット側のblobを読みます。<a href="https://git-scm.com/docs/gitdatamodel#index" target="_blank" rel="noreferrer">Git公式のデータモデル</a> · <a href="https://git-scm.com/docs/git-ls-files#_output" target="_blank" rel="noreferrer">git-ls-files</a> · <a href="https://git-scm.com/docs/gitrevisions#_specifying_revisions" target="_blank" rel="noreferrer">gitrevisions</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git ls-files --stage</span></span>
<span class="line"><span>100644 2fa992c0 0  keep.txt</span></span>
<span class="line"><span>100644 05cbe44d 0  score.txt</span></span>
<span class="line"><span>$ git show &#39;:score.txt&#39;</span></span>
<span class="line"><span>score=10</span></span>
<span class="line"><span>$ git show &#39;HEAD:score.txt&#39;</span></span>
<span class="line"><span>score=0</span></span></code></pre></div><p>表示したオブジェクトIDは先頭8桁です。</p><p>初回のコミットから変更していない <code>keep.txt</code> もindexにあります。次のtreeでもこのパスから同じblobを参照するので、変更のないファイルもスナップショットに含まれます。作業ツリーだけの <code>bonus.txt</code> は一覧にありません。<code>score.txt</code> の項目からは、差分を適用しなくてもステージした <code>score=10</code> を読み取れます。<a href="/study/tools/git-objects.html">Gitの保存モデル</a></p><h2 id="次のコミットに入る内容を確かめる" tabindex="-1">次のコミットに入る内容を確かめる <a class="header-anchor" href="#次のコミットに入る内容を確かめる" aria-label="Permalink to &quot;次のコミットに入る内容を確かめる&quot;">​</a></h2><p>独立した検証リポジトリでは、コミットする前に <code>git write-tree</code> で現在のindexからtreeを書き出しました。このコマンドが作るのはtreeオブジェクトで、HEADは進みません。そのまま、内容を選ぶオプションやパス指定を付けずにコミットすると、新しい <code>HEAD^{tree}</code> は先ほど作ったtreeと同じIDになりました。<a href="https://git-scm.com/docs/git-write-tree" target="_blank" rel="noreferrer">git-write-tree</a> · <a href="https://git-scm.com/docs/git-commit#_description" target="_blank" rel="noreferrer">git-commit</a></p><p>コミット前の <code>git write-tree</code> と、コミット後の <code>git rev-parse &#39;HEAD^{tree}&#39;</code> は、どちらも <code>255aed01…</code> を返しました。<code>git ls-tree HEAD</code> で新しいtreeを読むと、<code>keep.txt</code> と <code>score.txt</code> の2項目があり、上のindexと同じblob IDを指しています。</p><p>コミット後、HEADとindexは <code>score=10</code>、作業ツリーには <code>score=20</code> が残りました。このため <code>git diff --cached</code> は空になり、<code>git diff</code> には <code>10 → 20</code> が残ります。<code>keep.txt</code> は新しいtreeにもあり、<code>bonus.txt</code> は未追跡のままです。<a href="https://git-scm.com/docs/git-diff#_description" target="_blank" rel="noreferrer">git-diff</a> · <a href="https://git-scm.com/docs/git-commit#_description" target="_blank" rel="noreferrer">git-commit</a></p><p><code>git commit -a</code> を使うと、Gitがすでに追跡しているファイルの変更や削除を先にステージします。新規の未追跡ファイルは <code>-a</code> の対象外です。コミット時に既知のパスを指定する方法にも別の規則があるので、この例ではindexをそのまま採用する場合に絞っています。<a href="https://git-scm.com/docs/git-commit#_description" target="_blank" rel="noreferrer">git-commit</a></p><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><details class="details custom-block"><summary>score=20を保存した直後、通常のコミットに入る値は？</summary><p>最後にステージした <code>score=10</code> です。<code>score=20</code> は作業ツリー側にあり、<code>git diff</code> でその差を確認できます。</p></details><details class="details custom-block"><summary>なぜ変更していない keep.txt も index にある？</summary><p>indexの項目は次のtreeを組み立てるために使います。変更していないパスも次のスナップショットに含まれ、元と同じblobを参照できます。</p></details><h2 id="検証範囲" tabindex="-1">検証範囲 <a class="header-anchor" href="#検証範囲" aria-label="Permalink to &quot;検証範囲&quot;">​</a></h2><p>2026年11月17日にWindowsのGit 2.39.2.windows.1で、LFのテキストファイルを置いた独立した検証リポジトリを使いました。<code>git ls-files --stage</code>、2種類の <code>git diff</code>、<code>git status --short</code>、<code>git show</code>、コミット前後のtreeと作業ツリーを照合しました。競合や <code>git commit -a</code>・パス指定の動作は、今回の実測には含めていません。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/tools/git-basics.html">Gitの基本</a> — 作業ツリーとステージングを操作し、差分を読んでみる。</li><li><a href="/study/tools/git-objects.html">Gitの保存モデル</a> — 次のスナップショットが、treeとblobとしてどう保存されるかを読む。</li><li>indexと作業ツリーに異なる版がある途中状態を、退避して再適用する仕組みを読む。<a href="/study/tools/git-stash.html">Git stashの内部構造 — 作業ツリーとindexの退避・再適用を追う</a></li><li>同じパスの内容をHEADからindexへ、indexから作業ツリーへ戻す場合を比べる。<a href="/study/tools/git-restore.html">Git restoreの仕組み — 履歴を動かさず、復元元と復元先を選ぶ</a></li><li>ブランチの先端を動かすとき、indexと作業ツリーをどこまで更新するかを比べる。<a href="/study/tools/git-reset.html">Gitのreset — HEAD・index・作業ツリーはどう変わるのか</a></li><li>同じ行を編集したマージ競合の例で、共通祖先と両側の内容をindexのステージ1・2・3から読む。<a href="/study/tools/git-three-way-merge.html">Gitのマージ — 共通祖先と3-way merge</a></li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://git-scm.com/docs/gitdatamodel#index" target="_blank" rel="noreferrer">Git公式 — データモデルのindex</a></li><li><a href="https://git-scm.com/docs/git-add#_description" target="_blank" rel="noreferrer">Git公式 — git-add</a> · <a href="https://git-scm.com/docs/git-ls-files#_output" target="_blank" rel="noreferrer">git-ls-files</a></li><li><a href="https://git-scm.com/docs/git-diff#_description" target="_blank" rel="noreferrer">Git公式 — git-diff</a> · <a href="https://git-scm.com/docs/git-status#_short_format" target="_blank" rel="noreferrer">git-status</a></li><li><a href="https://git-scm.com/docs/git-write-tree" target="_blank" rel="noreferrer">Git公式 — git-write-tree</a> · <a href="https://git-scm.com/docs/git-commit#_description" target="_blank" rel="noreferrer">git-commit</a></li></ul>`,21))])}const A=r(h,[["render",f]]);export{u as __pageData,A as default};
